SELECT bucket, entity, set_product_sales, set_returns FROM (SELECT CAST(DATE_TRUNC('MONTH', posting_date) AS DATE) AS bucket, entity, COALESCE(SUM(CASE WHEN account_id IN ('4000', '4010', '4020', '4030', '4040', '4050', '4060', '4070', '4080', '4090') THEN CASE WHEN account_id IN ('4000', '4010', '4020', '4030', '4040', '4050', '4060', '4070', '4080', '4090') THEN -CAST(amount AS DECIMAL(38, 6)) END END), 0) AS set_product_sales, COALESCE(SUM(CASE WHEN account_id IN ('4900') THEN CASE WHEN account_id IN ('4900') THEN CAST(amount AS DECIMAL(38, 6)) END END), 0) AS set_returns FROM journal WHERE posting_date >= CAST('2025-01-01' AS DATE) AND posting_date < CAST('2025-07-01' AS DATE) GROUP BY CAST(DATE_TRUNC('MONTH', posting_date) AS DATE), entity) AS scan ORDER BY bucket, entity
